import { readFileSync, statSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'
import { describe, expect, it } from 'vitest'

// The favicon, app icons and manifest icons are generated by scripts/generate-icons.mjs from
// public/brand/sineva-symbol-original.svg. These tests check the committed output: sizes, solid
// backgrounds, how much of the canvas the symbol fills, and the maskable safe zone. They read the
// pixels rather than trusting the script's parameters, so a change to either side is caught.
const root = (path: string) => fileURLToPath(new URL(`../../${path}`, import.meta.url))
const CANVAS = [255, 255, 255] // --color-canvas (see manifest.test.ts for the token check)

type Raster = { data: Buffer; width: number; height: number; channels: number }
async function raster(path: string | Buffer): Promise<Raster> {
  const { data, info } = await sharp(path).raw().toBuffer({ resolveWithObject: true })
  return { data, width: info.width, height: info.height, channels: info.channels }
}

// Pixels that differ from the solid background by more than the antialiasing fringe.
function inkPixels({ data, width, height, channels }: Raster, background = CANVAS) {
  const ink: { x: number; y: number }[] = []
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * channels
      const distance = Math.max(
        Math.abs(data[i] - background[0]),
        Math.abs(data[i + 1] - background[1]),
        Math.abs(data[i + 2] - background[2]),
      )
      if (distance > 24) ink.push({ x, y })
    }
  }
  return ink
}

function extent(pixels: { x: number; y: number }[]) {
  const xs = pixels.map((p) => p.x)
  const ys = pixels.map((p) => p.y)
  return {
    width: Math.max(...xs) - Math.min(...xs) + 1,
    height: Math.max(...ys) - Math.min(...ys) + 1,
  }
}

const corners = ({ data, width, height, channels }: Raster) =>
  [
    [0, 0],
    [width - 1, 0],
    [0, height - 1],
    [width - 1, height - 1],
  ].map(([x, y]) =>
    Array.from(data.subarray((y * width + x) * channels, (y * width + x) * channels + 3)),
  )

describe('favicon.ico', () => {
  const ico = readFileSync(root('src/app/favicon.ico'))
  const count = ico.readUInt16LE(4)
  const entries = Array.from({ length: count }, (_, n) => {
    const at = 6 + n * 16
    return {
      width: ico[at] || 256,
      height: ico[at + 1] || 256,
      size: ico.readUInt32LE(at + 8),
      offset: ico.readUInt32LE(at + 12),
    }
  })

  it('is a valid icon directory holding 16, 32 and 48 px images', () => {
    expect(ico.readUInt16LE(0)).toBe(0)
    expect(ico.readUInt16LE(2)).toBe(1)
    expect(entries.map((e) => [e.width, e.height])).toEqual([
      [16, 16],
      [32, 32],
      [48, 48],
    ])
  })

  it('stores every image as PNG with a size that matches its directory entry', async () => {
    for (const entry of entries) {
      const image = ico.subarray(entry.offset, entry.offset + entry.size)
      expect(image.subarray(1, 4).toString('latin1')).toBe('PNG')
      const meta = await sharp(image).metadata()
      expect([meta.width, meta.height]).toEqual([entry.width, entry.height])
    }
  })

  it('keeps the symbol legible at 16 px: transparent corners, a symbol that spans the grid', async () => {
    const small = ico.subarray(entries[0].offset, entries[0].offset + entries[0].size)
    const { data, info } = await sharp(small)
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true })
    const opaque: { x: number; y: number }[] = []
    for (let y = 0; y < info.height; y++) {
      for (let x = 0; x < info.width; x++) {
        if (data[(y * info.width + x) * 4 + 3] > 128) opaque.push({ x, y })
      }
    }
    const { width, height } = extent(opaque)
    // At 16 px every pixel counts: the symbol has to use nearly the whole grid, and be solid
    // enough to read (not a fringe of half-transparent pixels).
    expect(Math.max(width, height)).toBeGreaterThanOrEqual(15)
    expect(opaque.length).toBeGreaterThanOrEqual(80)
    expect(data[3]).toBe(0)
  })
})

describe('icon.svg', () => {
  const svg = readFileSync(root('src/app/icon.svg'), 'utf8')

  // The source art is 180 KB; the optimized copy is about 41 KB (5 KB gzipped, which is what a
  // browser downloads). The budget leaves room for a re-trace but not for the unoptimized file.
  it('stays small and is a self-contained vector', () => {
    expect(statSync(root('src/app/icon.svg')).size).toBeLessThanOrEqual(50_000)
    expect(svg).toMatch(/^<svg [^>]*viewBox="0 0 [\d.]+ [\d.]+"/)
    expect(svg).not.toMatch(/<script|<image|<foreignObject|href=/)
  })

  it('crops tightly to the symbol so the tab icon is not mostly padding', async () => {
    const { data, info } = await sharp(Buffer.from(svg), { density: 72 })
      .resize(256, 256, { fit: 'inside' })
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true })
    const opaque: { x: number; y: number }[] = []
    for (let y = 0; y < info.height; y++) {
      for (let x = 0; x < info.width; x++) {
        if (data[(y * info.width + x) * 4 + 3] > 128) opaque.push({ x, y })
      }
    }
    const { width, height } = extent(opaque)
    expect(Math.max(width, height) / 256).toBeGreaterThan(0.96)
  })
})

describe('apple-icon.png', () => {
  const file = root('src/app/apple-icon.png')

  it('is 180 px with an opaque canvas-colored background', async () => {
    const meta = await sharp(file).metadata()
    expect([meta.format, meta.width, meta.height, meta.hasAlpha]).toEqual(['png', 180, 180, false])
    for (const corner of corners(await raster(file))) expect(corner).toEqual(CANVAS)
  })

  it('draws the symbol at about 70 percent of the canvas', async () => {
    const { width, height } = extent(inkPixels(await raster(file)))
    expect(Math.max(width, height) / 180).toBeGreaterThan(0.66)
    expect(Math.max(width, height) / 180).toBeLessThan(0.74)
  })
})

describe.each([192, 512])('brand/icon-%i.png (manifest, maskable safe zone)', (size) => {
  const file = root(`public/brand/icon-${size}.png`)

  it(`is ${size} px with an opaque canvas-colored background`, async () => {
    const meta = await sharp(file).metadata()
    expect([meta.format, meta.width, meta.height, meta.hasAlpha]).toEqual([
      'png',
      size,
      size,
      false,
    ])
    for (const corner of corners(await raster(file))) expect(corner).toEqual(CANVAS)
  })

  it('draws the symbol at about 60 percent of the canvas', async () => {
    const { width, height } = extent(inkPixels(await raster(file)))
    expect(Math.max(width, height) / size).toBeGreaterThan(0.56)
    expect(Math.max(width, height) / size).toBeLessThan(0.64)
  })

  // The maskable spec keeps important content inside a circle of radius 40 percent of the side,
  // the smallest shape any launcher mask leaves visible. A tolerance of 1 px covers antialiasing.
  it('keeps every symbol pixel inside the maskable safe circle', async () => {
    const pixels = inkPixels(await raster(file))
    const center = size / 2
    const farthest = Math.max(
      ...pixels.map((p) => Math.hypot(p.x + 0.5 - center, p.y + 0.5 - center)),
    )
    expect(farthest).toBeLessThanOrEqual(size * 0.4 + 1)
  })
})
